import sailpoint.api.Provisioner;
import sailpoint.object.Application;
import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningProject;

String appName = "Peachtree AD (iamlab)";

Identity identity = context.getObjectByName(Identity.class, identityName);
if (identity == null) {
    throw new Exception("PT Leaver: identity not found: " + identityName);
}

Application ad = context.getObjectByName(Application.class, appName);
if (ad == null) {
    throw new Exception("PT Leaver: application " + appName + " not found");
}

// Idempotent: nothing to remove if there is no account or it is already disabled
Link link = identity.getLink(ad);
if (link == null) {
    return "SKIPPED: " + identityName + " has no Peachtree AD account";
}
if (link.isDisabled()) {
    return "SKIPPED: " + identityName + " Peachtree AD account is already disabled";
}

ProvisioningPlan plan = new ProvisioningPlan();
plan.setIdentity(identity);

AccountRequest request = new AccountRequest();
request.setApplication(appName);
request.setNativeIdentity(link.getNativeIdentity());
request.setOperation(AccountRequest.Operation.Disable);
plan.add(request);

Provisioner provisioner = new Provisioner(context);
ProvisioningProject project = provisioner.compile(plan);
provisioner.execute(project);

return "DISABLED: Peachtree AD account " + link.getNativeIdentity() + " for " + identityName;
